<?php namespace App\Http\Controllers; use App\Models\{Customer,Furniture,Order,OrderItem,InventoryTransaction}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; class OrderController extends Controller { public function index(){return view('orders.index',['orders'=>Order::with('customer')->latest()->paginate(10)]);} public function create(){return view('orders.create',['customers'=>Customer::all(),'furnitures'=>Furniture::where('quantity','>',0)->get()]);} public function store(Request $r){$r->validate(['customer_id'=>'required|exists:customers,id','items'=>'required|array','items.*.furniture_id'=>'required|exists:furnitures,id','items.*.quantity'=>'required|integer|min:1']);DB::transaction(function()use($r,&$order){$order=Order::create(['order_number'=>'ORD-'.strtoupper(Str::random(7)),'customer_id'=>$r->customer_id,'user_id'=>$r->user()->id,'subtotal'=>0,'total'=>0]);$total=0;foreach($r->items as $line){$f=Furniture::lockForUpdate()->findOrFail($line['furniture_id']);if($f->quantity<$line['quantity'])throw \Illuminate\Validation\ValidationException::withMessages(['items'=>'Insufficient stock for '.$f->name]);$amount=$f->price*$line['quantity'];OrderItem::create(['order_id'=>$order->id,'furniture_id'=>$f->id,'quantity'=>$line['quantity'],'price'=>$f->price,'line_total'=>$amount]);$f->decrement('quantity',$line['quantity']);InventoryTransaction::create(['furniture_id'=>$f->id,'type'=>'sale','quantity'=>$line['quantity'],'notes'=>$order->order_number]);$total+=$amount;}$order->update(['subtotal'=>$total,'total'=>$total]);});return redirect()->route('orders.show',$order)->with('success','Order completed.');} public function show(Order $order){$order->load('customer','items.furniture');return view('orders.show',compact('order'));} public function invoice(Order $order){$order->load('customer','items.furniture');return view('orders.invoice',compact('order'));} }
